import json
import pathlib
import sys


def legacy_total(values):
    return sum(values)


if __name__ == '__main__':
    if len(sys.argv) != 3 or sys.argv[1] != 'report':
        raise SystemExit(2)
    records = json.loads(pathlib.Path(sys.argv[2]).read_text(encoding='utf-8'))
    print(json.dumps({'count': len(records), 'total_cents': sum(row['amount_cents'] for row in records)}))
